                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                objs.append({'c':cid,'shp':sorted([(y-min(ys),x-min(xs)) for y,x in comp]),'w':max(xs)-min(xs)+1,'h':max(ys)-min(ys)+1})
    return objs
def f(g):
    cs=comps(g)
    Wd=sum(o['w'] for o in cs); Hg=max(o['h'] for o in cs)
